return ['domain'=>'acfml','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'uk','project-id-version'=>'Advanced Custom Fields Multilingual 5.2.0','pot-creation-date'=>'2026-10-20 11:28+0000','po-revision-date'=>'2026-10-20 11:28+0000','x-generator'=>'PTC (Private Translation Cloud)','messages'=>['Advanced Custom Fields Multilingual'=>'Advanced Custom Fields Multilingual','https://wpml.org/documentation/wpml-core-and-add-on-plugins/acfml/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/acfml/','Adds compatibility between WPML and Advanced Custom Fields | <a href="https://wpml.org/documentation/translating-your-contents/acf/?utm_source=plugin&utm_medium=gui&utm_campaign=acfml">Documentation</a>'=>'Додає сумісність між WPML та Advanced Custom Fields | <a href="https://wpml.org/documentation/translating-your-contents/acf/?utm_source=plugin&utm_medium=gui&utm_campaign=acfml">Документація</a>','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com/'=>'http://www.onthegosystems.com/','Displayed when editing an ACF field in a translation, showing its value in the original language; %1$s and %2$s turn the string into bold, and %3$s is the actual original value.%1$sOriginal%2$s: %3$s'=>'%1$sОригінал%2$s: %3$s','This type of ACF field will always be set to "Copy once".'=>'Цей тип поля ACF завжди матиме значення «Копіювати один раз».','ACF field name:'=>'Назва поля ACF:','ACF field type:'=>'Тип поля ACF:','Translation preferences'=>'Налаштування перекладу','What to do with field\'s value when post/page is going to be translated'=>'Що робити зі значенням поля, коли запис/сторінка буде перекладатися','Translate (your current setting, no longer offered for this field type)'=>'Перекладати (ваше поточне налаштування, більше не пропонується для цього типу поля)','Kept because it is your current setting. This value is no longer offered for this field type.'=>'Збережено, оскільки це ваше поточне налаштування. Це значення більше не пропонується для цього типу поля.','Not recommended for this field type.'=>'Не рекомендовано для цього типу поля.','Translated pages start without this content.'=>'Перекладені сторінки починаються без цього вмісту.','Editable in other languages, and starts empty.'=>'Можна редагувати іншими мовами, спочатку порожнє.','Visitors in every language always see exactly what the original shows.'=>'Відвідувачі всіма мовами завжди бачать саме те, що відображається в оригіналі.','Shown locked in other languages, so it cannot be edited there.'=>'Відображається заблокованим іншими мовами, тому його не можна там редагувати.','Starts the same as the original, then each language goes its own way.'=>'Спочатку таке саме, як оригінал, потім кожна мова має власний вміст.','Editable in every language, and permanently yours to maintain by hand.'=>'Можна редагувати кожною мовою, ви підтримуєте його вручну.','Visitors see this in their own language.'=>'Відвідувачі бачать це своєю мовою.','Filled by the translation and edited in the translation editor.'=>'Заповнюється перекладом і редагується в редакторі перекладів.','Edit the field to set the translation preference.'=>'Відредагуйте поле, щоб установити налаштування перекладу.','ACFML is updating translation preferences for strings in Gutenberg Blocks. Keep using your site as usual. This notice will disappear when the process is done.'=>'ACFML оновлює налаштування перекладу для рядків у блоках Gutenberg. Продовжуйте користуватися сайтом як зазвичай. Це повідомлення зникне після завершення процесу.','ACFML is enabled but not effective. It requires WPML in order to work.'=>'ACFML увімкнено, але він не працює. Для його роботи потрібен WPML.','ACFML is enabled but not effective. It requires Advanced Custom Fields or ACF PRO in order to work.'=>'ACFML увімкнено, але він не працює. Для його роботи потрібен Advanced Custom Fields або ACF PRO.','Activate Advanced Custom Fields'=>'Активувати Advanced Custom Fields','Install Advanced Custom Fields'=>'Встановити Advanced Custom Fields','Field groups are set to "Translatable" in WPML settings, which prevents ACF fields from being translated.'=>'Групи полів мають значення «Перекладається» в налаштуваннях WPML, що заважає перекладу полів ACF.','This is almost never intended.'=>'Це майже ніколи не робиться навмисно.','A configuration file (wpml-config.xml) controls this setting on this site, so it cannot be changed from here. Edit that file, or ask whoever maintains it to set the ACF field group post type to Not translatable.'=>'Файл конфігурації (wpml-config.xml) керує цим налаштуванням на цьому сайті, тому його не можна змінити звідси. Відредагуйте цей файл або попросіть того, хто його підтримує, встановити для типу запису групи полів ACF значення «Не перекладати».','Field group copies already created in other languages stay on the site. Changing this setting does not delete them.'=>'Копії груп полів, уже створені іншими мовами, залишаються на сайті. Зміна цього налаштування не видаляє їх.','Set field groups to Not translatable'=>'Встановити для груп полів значення «Не перекладати»','Why this matters'=>'Чому це важливо','If any field is set to "Translatable", WPML will re-translate the %d posts using this field group.'=>'Якщо будь-яке поле має значення «Перекладається», WPML повторно перекладе %d записів, що використовують цю групу полів.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to 1 minute.'=>'Деякі записи, що використовують цю групу полів, мають переклади. Після зміни параметра перекладу WPML потрібно оновити статус перекладу записів. Це може зайняти до 1 хвилини.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to %d hours.'=>'Деякі записи, що використовують цю групу полів, мають переклади. Після зміни параметра перекладу WPML потрібно оновити статус перекладу записів. Це може зайняти до %d годин.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to %d minutes.'=>'Деякі записи, що використовують цю групу полів, мають переклади. Після зміни параметра перекладу WPML потрібно оновити статус перекладу записів. Це може зайняти до %d хвилин.','Locked by WPML so that ACF fields stay translatable. Click here to unlock and change it anyway.'=>'Заблоковано WPML, щоб поля ACF залишалися доступними для перекладу. Натисніть тут, щоб розблокувати та все одно змінити це.','Set translation preferences for the attached taxonomy'=>'Встановити налаштування перекладу для прикріпленої таксономії','Set translation preferences for the attached post type'=>'Встановити налаштування перекладу для прикріпленого типу запису','If you want to translate your fields, go to the WPML Settings page and make the taxonomy attached to this field group translatable. '=>'Якщо ви хочете перекласти свої поля, перейдіть на сторінку налаштувань WPML і зробіть таксономію, прикріплену до цієї групи полів, доступною для перекладу. ','If you want to translate your fields, go to the WPML Settings page and %1$smake the post type attached to this field group translatable%2$s.'=>'Якщо ви хочете перекласти свої поля, перейдіть на сторінку налаштувань WPML і %1$sзробіть тип запису, прикріплений до цієї групи полів, доступним для перекладу%2$s.','Expert'=>'Експертний','Same content in every language, translated'=>'Однаковий вміст для всіх мов, з перекладом','Each language has its own content'=>'Кожна мова має власний вміст','Translate is not offered on container fields, because it replaces the value your theme reads. The fields inside carry their own preferences.'=>'Варіант «Перекладати» не пропонується для полів-контейнерів, оскільки він замінює значення, яке зчитує ваша тема. Поля всередині мають власні налаштування.','Translate lets each language point at its own address, which an external link often needs. A link to a page on this site already points at that page in the reader\'s language, so leave it as it is.'=>'«Translate» дозволяє кожній мові вказувати на власну адресу, що часто потрібно для зовнішніх посилань. Посилання на сторінку цього сайту вже вказує на цю сторінку мовою читача, тому залиште його як є.','Translate sends the link text and the URL. The target keeps the value you set, and a URL you leave as it is points at the page in the reader\'s language.'=>'«Translate» надсилає текст посилання та URL-адресу. Ціль зберігає встановлене вами значення, а URL-адреса, яку ви залишаєте як є, вказує на сторінку мовою читача.','Translating an address produces one that does not exist. An e-mail address is the same in every language.'=>'Переклад адреси створює таку, якої не існує. Адреса електронної пошти однакова всіма мовами.','A color code is not language content. Translating it changes the color your visitors see.'=>'Код кольору не є мовним вмістом. Його переклад змінює колір, який бачать ваші відвідувачі.','The stored value is a fixed date format that your theme reads. Translating it breaks the format.'=>'Збережене значення — це фіксований формат дати, який зчитує ваша тема. Переклад порушує формат.','The stored value is the choice key, not the label your visitors see. Translating it stops the key from matching your choices. Translate the labels in <b>String Translation</b> instead.'=>'Збережене значення — це ключ вибору, а не мітка, яку бачать ваші відвідувачі. Переклад призведе до того, що ключ не відповідатиме вашим варіантам. Замість цього перекладіть мітки в <b>String Translation</b>.','This value is read by your theme or plugin code. A translated value can stop matching what the code expects.'=>'Це значення зчитується кодом вашої теми або плагіна. Перекладене значення може перестати відповідати тому, що очікує код.','The file decides this again on every import, so changes made elsewhere do not stick.'=>'Файл вирішує це знову при кожному імпорті, тому зміни, зроблені в іншому місці, не зберігаються.','Edit %s, or remove the entry there, to manage this field on this screen.'=>'Відредагуйте %s або видаліть там запис, щоб керувати цим полем на цьому екрані.','Edit the configuration file, or remove the entry there, to manage this field on this screen.'=>'Відредагуйте файл конфігурації або видаліть там запис, щоб керувати цим полем на цьому екрані.','That is not the value selected above. Saving this field group applies the value above.'=>'Це не те значення, яке вибрано вище. Збереження цієї групи полів застосовує значення вище.','This field group is also in %s. That file re-applies these settings the next time the group is synced.'=>'Ця група полів також є в %s. Цей файл повторно застосує ці налаштування під час наступної синхронізації групи.','Locked. Managed by your theme, in its wpml-config.xml file.'=>'Заблоковано. Керується вашою темою у файлі wpml-config.xml.','Locked. Managed by a plugin, in its wpml-config.xml file.'=>'Заблоковано. Керується плагіном у файлі wpml-config.xml.','Locked. Managed by a configuration file WPML downloaded for one of your plugins or themes.'=>'Заблоковано. Керується файлом конфігурації, який WPML завантажив для одного з ваших плагінів або тем.','Locked. Managed by the custom XML configuration saved in WPML settings.'=>'Заблоковано. Керується спеціальною конфігурацією XML, збереженою в налаштуваннях WPML.','Locked. Managed by a configuration file on this site.'=>'Заблоковано. Керується файлом конфігурації на цьому сайті.','Set in the field group "%s", which uses the same field name.'=>'Встановлено в групі полів «%s», яка використовує таку саму назву поля.','Set in the field group\'s local JSON file.'=>'Встановлено в локальному файлі JSON групи полів.','Set in the field group\'s local JSON file, %s.'=>'Встановлено в локальному файлі JSON групи полів, %s.','Registered with PHP by your theme or a plugin.'=>'Зареєстровано за допомогою PHP вашою темою або плагіном.','Set on the WPML Settings screen (Custom Fields Translation).'=>'Встановлено на екрані налаштувань WPML (Переклад спеціальних полів).','Set here, on this screen.'=>'Встановлено тут, на цьому екрані.','Right now this field is translated, so visitors see it in their own language.'=>'Зараз це поле перекладається, тому відвідувачі бачать його своєю мовою.','Right now this field stays identical in every language.'=>'Зараз це поле залишається ідентичним всіма мовами.','Right now this field starts as a copy in every language, then each language keeps its own.'=>'Зараз це поле починається як копія кожною мовою, потім кожна мова має власне значення.','Right now this field stays out of translations.'=>'Зараз це поле не перекладається.','Don\'t translate'=>'Не перекладати','Copy'=>'Копіювати','Copy once'=>'Копіювати один раз','Translate'=>'Перекладати','Field groups'=>'Групи полів','Fields'=>'Поля','Posts'=>'Записи','Review them one by one'=>'Переглянути їх по черзі','Apply the recommended setup to %d group'=>'Застосувати рекомендовані налаштування до %d групи' . "\0" . 'Застосувати рекомендоване налаштування до всіх %d' . "\0" . 'Застосувати рекомендоване налаштування до всіх %d','%d ACF field group is not configured for translation.'=>'%d група полів ACF не налаштована для перекладу.' . "\0" . '%d групи полів ACF не налаштовано для перекладу.' . "\0" . '%d груп полів ACF не налаштовано для перекладу.','%d post'=>'%d запис' . "\0" . '%d записи' . "\0" . '%d записів','%1$s field, used on %2$s, would be skipped and stay in %3$s.'=>'%1$s поле, яке використовується в %2$s, буде пропущено та залишиться мовою: %3$s.' . "\0" . '%1$s поля, які використовуються в %2$s, буде пропущено та вони залишаться мовою: %3$s.' . "\0" . '%1$s полів, які використовуються в %2$s, буде пропущено та вони залишаться мовою: %3$s.','%1$s field, used on %2$s, would be skipped and stay untranslated.'=>'%1$s поле, яке використовується в %2$s, буде пропущено й воно залишиться неперекладеним.' . "\0" . '%1$s поля, які використовуються в %2$s, буде пропущено й вони залишаться неперекладеними.' . "\0" . '%1$s полів, які використовуються в %2$s, буде пропущено й вони залишаться неперекладеними.','You are not allowed to change the translation setup of ACF field groups.'=>'Вам не дозволено змінювати налаштування перекладу груп полів ACF.','You are not allowed to change the WPML translation settings on this site.'=>'Вам не дозволено змінювати налаштування перекладу WPML на цьому сайті.','To change the translation options for custom fields, edit the field group "%s".'=>'Щоб змінити параметри перекладу для спеціальних полів, відредагуйте групу полів «%s».','These fields come from ACF’s Local JSON files. To change their translation options, go to ACF → Field Groups, sync them, and then edit their settings.'=>'Ці поля походять із локальних файлів JSON ACF. Щоб змінити їхні параметри перекладу, перейдіть до ACF → Групи полів, синхронізуйте їх, а потім відредагуйте їхні налаштування.','This field and its translation setting are registered via PHP by your theme or plugin. Changes made here will override the original configuration.'=>'Це поле та його налаштування перекладу зареєстровані через PHP вашою темою або плагіном. Зміни, зроблені тут, замінять початкову конфігурацію.','ACF translation setup'=>'Налаштування перекладу ACF','Translation setup'=>'Налаштування перекладу','You are not allowed to review the translation setup of ACF field groups.'=>'Вам не дозволено переглядати налаштування перекладу груп полів ACF.','Field group'=>'Група полів','Setup'=>'Налаштування','Actions'=>'Дії','This site has no ACF field groups yet.'=>'На цьому сайті ще немає груп полів ACF.','Alert:'=>'Попередження:','How to do that'=>'Як це зробити','View fields'=>'Переглянути поля','Open Dashboard'=>'Відкрити панель керування','Apply the recommended setup'=>'Застосувати рекомендовані налаштування','Every field group stored in this site’s database already has a translation setup.'=>'Кожна група полів, збережена в базі даних цього сайту, вже має налаштування перекладу.','Back to the field groups'=>'Назад до груп полів','Every field in those groups then gets the translation preference WPML recommends for its field type. A preference that was set by hand in one of them is replaced.'=>'Кожне поле в цих групах отримує налаштування перекладу, яке WPML рекомендує для його типу поля. Налаштування, встановлене вручну в одному з них, буде замінено.','Field groups that come from your theme, a plugin’s code, or an acf-json file are not changed. They cannot be saved from here.'=>'Групи полів, що походять із вашої теми, коду плагіна або файлу acf-json, не змінюються. Їх не можна зберегти звідси.','Cancel'=>'Скасувати','%d field group.'=>'%d група полів.' . "\0" . '%d групи полів.' . "\0" . '%d груп полів.','All of them have a translation setup.'=>'Усі вони мають налаштування перекладу.','%d is not configured.'=>'%d не налаштована.' . "\0" . '%d не налаштовано.' . "\0" . '%d не налаштовано.','Apply recommended setup to the %d unconfigured group'=>'Застосувати рекомендоване налаштування до %d неналаштованої групи' . "\0" . 'Застосувати рекомендоване налаштування до всіх %d неналаштованих груп' . "\0" . 'Застосувати рекомендоване налаштування до всіх %d неналаштованих груп','This sets %1$d field group to “%2$s”.'=>'Це встановлює для %1$d групи полів значення «%2$s».' . "\0" . 'Це встановлює для %1$d груп полів значення «%2$s».' . "\0" . 'Це встановлює для %1$d груп полів значення «%2$s».','%d field group is defined in code, so it cannot be configured from here.'=>'%d група полів визначена в коді, тому її не можна налаштувати звідси.' . "\0" . '%d групи полів визначено в коді, тому їх не можна налаштувати звідси.' . "\0" . '%d груп полів визначено в коді, тому їх не можна налаштувати звідси.','Not configured'=>'Не налаштовано','Not configured (defined in code)'=>'Не налаштовано (визначено в коді)','Set for each field (defined in code)'=>'Встановлено для кожного поля (визначено в коді)','Set for each field in WPML Settings (defined in code)'=>'Установлено для кожного поля в налаштуваннях WPML (визначено в коді)','%d field set manually'=>'%d поле встановлено вручну' . "\0" . '%d поля налаштовано вручну' . "\0" . '%d полів налаштовано вручну','Nothing decides how these fields are translated. Set %s on the fields in the code that registers this group.'=>'Ніщо не визначає, як перекладаються ці поля. Встановіть %s для полів у коді, який реєструє цю групу.','from an acf-json file'=>'з файлу acf-json','from an acf-json file that is newer than this site’s copy'=>'з файлу acf-json, який новіший за копію на цьому сайті','from your theme or a plugin’s code'=>'з вашої теми або коду плагіна','%d field group now uses the recommended setup.'=>'%d група полів тепер використовує рекомендоване налаштування.' . "\0" . '%d групи полів тепер використовують рекомендоване налаштування.' . "\0" . '%d груп полів тепер використовують рекомендоване налаштування.','%d field group has a newer acf-json file waiting to be synced, so that file decides its setup.'=>'%d група полів має новіший файл acf-json, що очікує на синхронізацію, тому цей файл визначає її налаштування.' . "\0" . '%d групи полів мають новіший файл acf-json, який очікує синхронізації, тому ці файли визначають їхнє налаштування.' . "\0" . '%d груп полів мають новіший файл acf-json, який очікує синхронізації, тому ці файли визначають їхнє налаштування.','Translation Option'=>'Параметр перекладу','Multilingual Setup'=>'Багатомовне налаштування','Loading...'=>'Завантаження...','Activate <b>String Translation</b>'=>'Активувати <b>string translation</b>','To translate field group names and labels, please %1$sinstall and activate WPML’s String Translation add-on%2$s.'=>'Щоб перекласти назви та мітки груп полів, будь ласка, %1$sвстановіть та активуйте аддон WPML String Translation%2$s.','Activate now'=>'Активувати зараз','Go back'=>'Назад','Set Up <b>Field Group Translation</b>'=>'Налаштувати <b>переклад груп полів</b>','To translate field labels from the <b>Translation Management</b> dashboard, finish the <b>Multilingual Setup</b> and save your field group settings.'=>'Щоб перекласти мітки полів на панелі <b>Керування перекладами</b>, завершіть <b>Багатомовне налаштування</b> та збережіть налаштування групи полів.','OK'=>'ОК','Translate Field Labels'=>'Перекласти мітки полів','To translate field labels, use the <b>Translation Management</b> dashboard.'=>'Щоб перекласти мітки полів, скористайтеся панеллю <b>Керування перекладами</b>.','Translate in <b>Translation Management</b>'=>'Перекласти в <b>керуванні перекладами</b>','Don’t want to translate field labels? %1$sLearn how to disable field label translation%2$s'=>'Не хочете перекладати мітки полів? %1$sДізнайтеся, як вимкнути переклад міток полів%2$s','Field Labels Partly Translated'=>'Мітки полів перекладені частково','Some field labels in this group are still untranslated. To finish translating them, go to the <b>Translation Management</b> dashboard.'=>'Деякі мітки полів у цій групі досі не перекладені. Щоб завершити їх переклад, перейдіть на панель <b>Керування перекладами</b>.','Fields Labels Already Translated'=>'Мітки полів уже перекладені','You already translated all field labels in this group. To update any translations, go to the <b>Translation Management</b> dashboard.'=>'Ви вже переклали всі мітки полів у цій групі. Щоб оновити будь-які переклади, перейдіть на панель <b>Керування перекладами</b>.','Go to <b>Translation Management</b>'=>'Перейти до <b>керування перекладами</b>','Select a translation option for this field group'=>'Виберіть параметр перекладу для цієї групи полів','Visitors everywhere see the same pages, in their own language. Text is translated; layout and settings stay identical.'=>'Відвідувачі всюди бачать однакові сторінки своєю мовою. Текст перекладається; макет і налаштування залишаються ідентичними.','You translate in the WPML <b>Translation Editor</b>. This works with automatic translation and <b>Translate Everything</b>.'=>'Ви перекладаєте у <b>Редакторі перекладів</b> WPML. Це працює з автоматичним перекладом та функцією <b>Перекладати все</b>.','Every language’s pages are written and maintained on their own. Fields start as a copy of the original, then go their own way.'=>'Сторінки кожною мовою пишуться та підтримуються окремо. Поля починаються як копія оригіналу, а потім змінюються незалежно.','You edit each language in the WordPress editor. WPML does not sync them afterwards, and automatic translation does not apply.'=>'Ви редагуєте кожну мову в редакторі WordPress. WPML не синхронізує їх після цього, і автоматичний переклад не застосовується.','If you are migrating a site, your existing field groups will use the Expert setup. This allows you to manually choose the translation option for each field in the group.'=>'Якщо ви переносите сайт, ваші існуючі групи полів використовуватимуть експертне налаштування. Це дозволяє вручну вибрати параметр перекладу для кожного поля в групі.','This option is %1$snot recommended%2$s for new field groups.'=>'Цей параметр %1$sне рекомендовано%2$s для нових груп полів.','Expert setup documentation'=>'Документація з експертного налаштування','Choose'=>'Вибрати','recommended for this site'=>'рекомендовано для цього сайту','Change option'=>'Змінити параметр','A Much Simpler Way to Translate Your ACF Sites'=>'Набагато простіший спосіб перекладу ваших сайтів ACF','This new release of ACFML allows you to configure multilingual sites in one-click, instead of many complex settings. Choose how to setup the translation for the fields.'=>'Цей новий випуск ACFML дозволяє налаштовувати багатомовні сайти в один клік замість багатьох складних налаштувань. Виберіть, як налаштувати переклад для полів.','Go to WPML Settings'=>'Перейти до налаштувань WPML','Need help choosing?'=>'Потрібна допомога з вибором?','Documentation'=>'Документація','How to translate field labels »'=>'Як перекласти мітки полів »','This setup translates field values.'=>'Це налаштування перекладає значення полів.','Translate field labels and dropdown choice labels separately. Find them under ACF Field Group in the <b>Translation Dashboard</b>.'=>'Перекладайте мітки полів і мітки варіантів вибору зі спадного списку окремо. Їх можна знайти в розділі «ACF Field Group» на <b>Панелі керування перекладами</b>.','Review these translation setting changes'=>'Переглянути ці зміни налаштувань перекладу','Saving this field group makes these changes:'=>'Збереження цієї групи полів вносить такі зміни:','%1$s: from “%2$s” to “%3$s”'=>'%1$s: з «%2$s» на «%3$s»','Switching to the field-by-field setup keeps every field\'s current setting. From here you set each field yourself.'=>'Перехід до покрокового налаштування зберігає поточне налаштування кожного поля. Звідси ви встановлюєте кожне поле самостійно.','New translations use the new settings automatically.'=>'Нові переклади автоматично використовують нові налаштування.','Not set'=>'Не встановлено','No posts with translations use this field group yet, so nothing has to be sent again.'=>'Жодні записи з перекладами ще не використовують цю групу полів, тому нічого не потрібно надсилати знову.','No terms with translations use this field group yet, so nothing has to be sent again.'=>'Жодні терміни з перекладами ще не використовують цю групу полів, тому нічого не потрібно надсилати знову.','No posts or terms with translations use this field group yet, so nothing has to be sent again.'=>'Жодні записи або терміни з перекладами ще не використовують цю групу полів, тому нічого не потрібно надсилати знову.','Only apply to new translations'=>'Застосовувати лише до нових перекладів','Checking how much content this affects...'=>'Перевірка того, на яку кількість вмісту це впливає...','Save changes'=>'Зберегти зміни','No, go back'=>'Ні, повернутися','Updating them sends them for translation again, which may use translation words.'=>'Їх оновлення знову надсилає їх на переклад, що може потребувати слів для перекладу.','Updating them marks their translations as needing an update. WPML does not send them for translation. You can send them from the Translation Dashboard.'=>'Їхнє оновлення позначає їхні переклади як такі, що потребують оновлення. WPML не надсилає їх на переклад автоматично. Ви можете надіслати їх із панелі керування перекладом.','Switching the setup applies the recommended value to the %d field in this group.'=>'Перемикання налаштування застосовує рекомендоване значення до %d поля в цій групі.' . "\0" . 'Зміна налаштування застосує рекомендоване значення до всіх %d полів у цій групі.' . "\0" . 'Зміна налаштування застосує рекомендоване значення до всіх %d полів у цій групі.','%d post already has translations that used the old settings.'=>'%d запис уже має переклади, у яких використовувалися старі налаштування.' . "\0" . '%d записи вже мають переклади, створені за старими налаштуваннями.' . "\0" . '%d записів уже мають переклади, створені за старими налаштуваннями.','%d term already has translations that used the old settings.'=>'%d термін уже має переклади, у яких використовувалися старі налаштування.' . "\0" . '%d терміни вже мають переклади, створені за старими налаштуваннями.' . "\0" . '%d термінів уже мають переклади, створені за старими налаштуваннями.','%d post uses this field group.'=>'%d запис використовує цю групу полів.' . "\0" . '%d записи використовують цю групу полів.' . "\0" . '%d записів використовують цю групу полів.','%d post is translated by hand, so WPML does not send it for translation.'=>'%d запис перекладено вручну, тому WPML не надсилає його на переклад.' . "\0" . '%d записи перекладено вручну, тому WPML не надсилає їх на переклад.' . "\0" . '%d записів перекладено вручну, тому WPML не надсилає їх на переклад.','Also update the %d existing post'=>'Також оновити %d наявний запис' . "\0" . 'Також оновити %d наявні записи' . "\0" . 'Також оновити %d наявних записів','Also update the %d existing term'=>'Також оновити %d наявний термін' . "\0" . 'Також оновити %d наявні терміни' . "\0" . 'Також оновити %d наявних термінів','Also update the %1$d existing posts and %2$d terms'=>'Також оновити %1$d наявних записів та %2$d термінів','Also update the %1$d existing post and %2$d terms'=>'Також оновити %1$d наявний запис та %2$d термінів','Also update the %1$d existing posts and %2$d term'=>'Також оновити %1$d наявних записів та %2$d термін','Also update the %1$d existing post and %2$d term'=>'Також оновити %1$d наявний запис та %2$d термін','This field group is shown on an Options page.'=>'Ця група полів відображається на сторінці опцій.','That is usually site-wide content like your header, footer, or global blocks.'=>'Зазвичай це загальносайтовий вміст, як-от заголовок, підвал або глобальні блоки.','To translate that content, use the %1$sWPML Translation Dashboard%2$s.'=>'Щоб перекласти цей вміст, скористайтеся %1$sWPML Translation Dashboard%2$s.','The options below still decide how each field behaves: translated, copied to every language, or kept separately per language.'=>'Параметри нижче все ще визначають поведінку кожного поля: перекладати, копіювати для кожної мови або зберігати окремо для кожної мови.','This field group also appears on an Options page.'=>'Ця група полів також з’являється на сторінці опцій.','That content is translated in the %1$sWPML Translation Dashboard%2$s, and the option you choose here decides how each of its fields behaves.'=>'Цей вміст перекладається в %1$sКошику перекладів WPML%2$s, а вибраний тут параметр визначає поведінку кожного з його полів.','Post Type Translation'=>'Переклад типів записів','Labels Translation'=>'Переклад міток','Taxonomy Translation'=>'Переклад таксономій','Finish the ACF <b>Multilingual Setup</b>'=>'Завершити <b>multilingual setup</b> для ACF','Before you can start translating, you need to edit each ACF Field Group to set a translation option for the fields inside it.'=>'Перш ніж почати переклад, вам потрібно відредагувати кожну групу полів ACF, щоб установити параметр перекладу для полів усередині неї.','Read more about %1$show to translate your ACF custom fields%2$s'=>'Докладніше про те, %1$sяк перекладати власні поля ACF%2$s','%1$sSet translation options%2$s'=>'%1$sУстановити параметри перекладу%2$s','Let\'s Start Translating!'=>'Почнімо перекладати!','Edit each Field Group to select a translation option for the fields inside it. If you don\'t set a translation option, you will not be able to translate your fields.'=>'Відредагуйте кожну групу полів, щоб вибрати параметр перекладу для полів усередині неї. Якщо ви не встановите параметр перекладу, ви не зможете перекладати свої поля.','A field in "%s" has the same name as a field in another field group. WPML stores translation preferences by field name, so two fields that share a name cannot be set differently.'=>'Поле в «%s» має таку саму назву, як і поле в іншій групі полів. WPML зберігає налаштування перекладу за назвою поля, тому два поля зі спільною назвою не можуть мати різні налаштування.','Some fields in "%s" have the same name as fields in other field groups. WPML stores translation preferences by field name, so fields that share a name cannot be set differently.'=>'Деякі поля в «%s» мають такі самі назви, як і поля в інших групах полів. WPML зберігає налаштування перекладу за назвою поля, тому поля зі спільною назвою не можуть мати різні налаштування.','What you set here may not be what your visitors get'=>'Те, що ви встановите тут, може відрізнятися від того, що побачать ваші відвідувачі','The field %1$s also exists in "%2$s". Rename this field to give it a translation setting of its own.'=>'Поле %1$s також існує в «%2$s». Перейменуйте це поле, щоб надати йому власне налаштування перекладу.','See both fields'=>'Переглянути обидва поля','Go to Media Translation settings'=>'Перейти до налаштувань перекладу медіафайлів','This content has ACF image, gallery, or file fields, but the alt text, caption, and title of their media will not be sent for translation. To include them, turn on "Translate Media Library texts when translating content" in WPML Media Translation settings.'=>'Цей вміст має поля ACF для зображень, галерей або файлів, але альтернативний текст, підпис і заголовок цих медіафайлів не будуть надіслані на переклад. Щоб включити їх, увімкніть «Translate Media Library texts when translating content» у налаштуваннях WPML Media Translation.','Media texts are not being translated'=>'Тексти медіафайлів не перекладаються','%1$sGo to Media Translation settings%2$s'=>'%1$sПерейти до налаштувань перекладу медіафайлів%2$s','Translate this Options page from the <b>Translation Dashboard</b>'=>'Перекладіть цю сторінку опцій через <b>Translation Dashboard</b>','You no longer need to switch the admin language to translate options manually. Translate all your options from the %1$sTranslation Dashboard%2$s.'=>'Вам більше не потрібно перемикати мову адмінпанелі, щоб перекладати опції вручну. Перекладайте всі свої опції через %1$sTranslation Dashboard%2$s.','Go to the Translation Dashboard'=>'Перейти до панелі керування перекладами','To change a finished translation, go to %1$sTranslation Jobs%2$s and click on the Edit Translation icon.'=>'Щоб змінити готовий переклад, перейдіть у %1$sЗавдання на переклад%2$s і натисніть на іконку «Редагувати переклад».','Go to Translation Jobs'=>'Перейти до завдань на переклад','WPML blocked this save to prevent data loss. The form sent about %1$s fields, but the PHP max_input_vars limit on this server (%2$s) let fewer through. Saving now would permanently delete the fields that did not arrive, including repeater rows. Nothing was saved. Ask your host to raise max_input_vars above %1$s and save again.'=>'WPML заблокував це збереження, щоб запобігти втраті даних. Форма надіслала близько %1$s полів, але ліміт PHP max_input_vars на цьому сервері дозволив пройти лише (%2$s). Збереження зараз призведе до безповоротного видалення полів, які не надійшли, включаючи рядки повторювачів. Нічого не було збережено. Попросіть свого хостинг-провайдера збільшити max_input_vars понад %1$s і спробуйте зберегти знову.','Save blocked to prevent data loss'=>'Збереження заблоковано для запобігання втраті даних','You need to %1$stranslate this post manually%2$s because the field groups attached to it use different translation options:'=>'Вам потрібно %1$sперекласти цей запис вручну%2$s, оскільки групи полів, прикріплені до нього, використовують різні параметри перекладу:','and %d more.'=>'та ще %d.','Show all field groups'=>'Показати всі групи полів','and %d more'=>'та ще %d','You need to translate this post manually because the field groups attached to it use different translation options: %s.'=>'Вам потрібно перекласти цей запис вручну, оскільки групи полів, прикріплені до нього, використовують різні параметри перекладу: %s.','Edit %s'=>'Редагувати %s','Go to documentation'=>'Перейти до документації','This field value is copied from the default language and will be kept in sync across languages.'=>'Значення цього поля копіюється з мови за замовчуванням і буде синхронізуватися між мовами.','Synchronise translations'=>'Синхронізувати переклади','Keep repeater and flexible sub-fields in the same order as the default language.'=>'Зберігати підполя повторювача та гнучкого вмісту в тому самому порядку, що й у мові за замовчуванням.','ACFML Synchronise translations'=>'ACFML Синхронізувати переклади','Translate ACF Local JSON and PHP-Registered Fields'=>'Перекласти локальні поля ACF, зареєстровані через JSON та PHP','ACF allows you to %1$sregister fields via PHP%2$s or %3$ssave field settings as JSON files%4$s. You can also save post types, taxonomies, or options pages settings to JSON files.'=>'ACF дозволяє %1$sреєструвати поля через PHP%2$s або %3$sзберігати налаштування полів як файли JSON%4$s. Ви також можете зберігати налаштування типів записів, таксономій або сторінок опцій у файлах JSON.','Configure how ACF Multilingual handles translations for these items.'=>'Налаштуйте, як ACF Multilingual обробляє переклади для цих елементів.','Sync <b>Translation Preferences</b> for Local Fields'=>'Синхронізувати <b>налаштування перекладу</b> для локальних полів','Don’t sync translation preferences'=>'Не синхронізувати налаштування перекладу','Sync once now'=>'Синхронізувати один раз зараз','Sync on every request (may affect performance)'=>'Синхронізувати при кожному запиті (може вплинути на продуктивність)','Register Labels for Translation'=>'Зареєструвати мітки для перекладу','Scans post types, taxonomies, options pages, and field groups stored in the "acf-json" directory, then registers their labels with WPML so you can translate them.'=>'Сканує типи записів, таксономії, сторінки опцій та групи полів, що зберігаються в каталозі «acf-json», а потім реєструє їхні мітки у WPML, щоб ви могли їх перекласти.','Don’t register labels'=>'Не реєструвати мітки','Register labels now'=>'Зареєструвати мітки зараз','Apply'=>'Застосувати','The synchronization of translation preferences is disabled.'=>'Синхронізацію налаштувань перекладу вимкнено.','Translation preferences synchronized.'=>'Налаштування перекладу синхронізовано.','The synchronization of translation preferences is enabled.'=>'Синхронізацію налаштувань перекладу увімкнено.','%s group'=>'%s група' . "\0" . '%s групи' . "\0" . '%s груп','%s post type'=>'%s тип запису' . "\0" . '%s типи записів' . "\0" . '%s типів записів','%s taxonomy'=>'%s таксономія' . "\0" . '%s таксономії' . "\0" . '%s таксономій','%s options page'=>'%s сторінка опцій' . "\0" . '%s сторінки опцій' . "\0" . '%s сторінок опцій','No local field groups, post types, taxonomies, or Options pages were found.'=>'Локальних груп полів, типів записів, таксономій або сторінок опцій не знайдено.','Used between elements of a two elements list and '=>' та ','Used before the last element of a three or more elements list, and '=>', та ','Successfully registered labels for %s.'=>'Успішно зареєстровано мітки для %s.','%1$sChange translation settings%2$s'=>'%1$sЗмінити налаштування перекладу%2$s','%1$sTranslate labels%2$s'=>'%1$sПерекласти мітки%2$s','Not translatable'=>'Не перекладається','Translatable'=>'Перекладається','only show translated items'=>'показувати лише перекладені елементи','use translation if available or fallback to default language'=>'використовувати переклад, якщо він доступний, або повернутися до мови за замовчуванням','This content must be translated manually due to the translation option you selected for the "%1$s" field group.'=>'Цей вміст потрібно перекладати вручну через параметр перекладу, вибраний для групи полів «%1$s».']];